// Generated by the platform from the OpenAPI contract (ADR-0016). Do not edit: it follows the design (C3).

import { call } from './client-runtime'
export { ApiError } from './client-runtime'

export interface CalcularComisionRequest {
  /** decimal(19,4,signed) */
  monto: number
  /** text(var,3,iso8859-1) */
  tipo: string
}

export interface CalcularComisionResponse {
  /** decimal(19,4,signed) */
  comision: number
}

export interface RealizarTransferenciaRequest {
  /** text(var,10,iso8859-1) */
  origen: string
  /** text(var,10,iso8859-1) */
  destino: string
  /** decimal(19,4,signed) */
  monto: number
  /** text(fixed,3,iso8859-1) */
  tipo: string
}

export interface RealizarTransferenciaResponse {
  /** integer(32,signed) */
  numero: number
  /** decimal(7,2,signed) */
  comision: number
  /** text(var,40,iso8859-1) */
  mensaje: string
}

export interface ConsultarComprobanteRequest {
  /** integer(32,signed) */
  numero: number
}

export interface ConsultarComprobanteResponse {
  /** text(var,11,iso8859-1) */
  numero: string
  /** text(var,20,iso8859-1) */
  monto: string
}

export interface Api {
  /** Calculates the commission of an operation: flat 0.50 up to 1000.00, otherwise 0.1% rounded half away from zero to 2 decimals, capped at 5.00, plus 1.00 for type INM applied after the cap. (rules RULE-001, RULE-002, RULE-003) */
  calcularComision(request: CalcularComisionRequest): Promise<CalcularComisionResponse>
  /** Validates and executes a transfer between two accounts in one transaction: debits amount plus commission from the origin, credits the amount to the destination, registers the transfer with the next sequential number and commits. (rules RULE-005, RULE-006, RULE-007, RULE-008, RULE-009, RULE-010) */
  realizarTransferencia(request: RealizarTransferenciaRequest): Promise<RealizarTransferenciaResponse>
  /** Returns the receipt of a transfer: the requested number and the stored amount formatted with two decimals, or a blank amount when the transfer does not exist (not an error). (rules RULE-004) */
  consultarComprobante(request: ConsultarComprobanteRequest): Promise<ConsultarComprobanteResponse>
}

/** The client over fetch; `baseUrl` is where the backend runs (same origin by default). */
export function createApi(baseUrl = '', fetchImpl: typeof fetch = (input, init) => fetch(input, init)): Api {
  return {
    calcularComision: (request) => call<CalcularComisionResponse>(fetchImpl, baseUrl, 'POST', '/api/transferencias/comisiones/calculo', request, true),
    realizarTransferencia: (request) => call<RealizarTransferenciaResponse>(fetchImpl, baseUrl, 'POST', '/api/transferencias/transferencias', request, true),
    consultarComprobante: (request) => call<ConsultarComprobanteResponse>(fetchImpl, baseUrl, 'GET', '/api/transferencias/transferencias/{numero}/comprobante', request, false),
  }
}
