```tsx
import { useState } from 'react'
import type { FormEvent } from 'react'
import { Screen, Card, Grid, Stack, TextField, SelectField, Button, Alert } from '@nexti/ds'
import { ApiError } from '../api/client'
import type { ScreenProps } from './types'

type Errors = {
  txtCuentaOrigen?: string
  txtCuentaDestino?: string
  txtMonto?: string
}

type Status = 'idle' | 'error' | 'success'

const TIPO_OPTIONS = [
  { value: '', label: 'Sin especificar' },
  { value: 'PRO', label: 'Programada (PRO)' },
  { value: 'INM', label: 'Inmediata (INM)' },
]

export default function TransferenciaScreen({ api }: ScreenProps) {
  const [origen, setOrigen] = useState('')
  const [destino, setDestino] = useState('')
  const [monto, setMonto] = useState('')
  const [tipo, setTipo] = useState('')

  const [errors, setErrors] = useState<Errors>({})
  const [status, setStatus] = useState<Status>('idle')
  const [comision, setComision] = useState('')
  const [mensaje, setMensaje] = useState('')
  const [busy, setBusy] = useState(false)

  const transferir = async (e?: FormEvent) => {
    e?.preventDefault()
    if (busy) return

    const found: Errors = {}
    if (origen.trim() === '') found.txtCuentaOrigen = 'Ingrese la cuenta origen'
    if (destino.trim() === '') found.txtCuentaDestino = 'Ingrese la cuenta destino'

    let montoNumber = NaN
    if (monto.trim() === '') {
      found.txtMonto = 'Ingrese el monto'
    } else {
      montoNumber = Number(monto.trim().replace(',', '.'))
      if (Number.isNaN(montoNumber)) found.txtMonto = 'El monto no es válido'
    }

    setErrors(found)
    if (Object.keys(found).length > 0) {
      setStatus('error')
      setComision('')
      setMensaje('No se pudo realizar la transferencia. Revise los campos marcados.')
      return
    }

    setBusy(true)
    try {
      const res = await api.realizarTransferencia({
        origen: origen.trim(),
        destino: destino.trim(),
        monto: montoNumber,
        tipo,
      })
      setStatus('success')
      setComision(res.comision.toFixed(2))
      setMensaje(res.mensaje)
    } catch (err) {
      setStatus('error')
      setComision('')
      setMensaje(err instanceof ApiError ? err.message : 'No se pudo realizar la transferencia.')
    } finally {
      setBusy(false)
    }
  }

  const cancelar = () => {
    setOrigen('')
    setDestino('')
    setMonto('')
    setTipo('')
    setErrors({})
    setComision('')
    setMensaje('')
    setStatus('idle')
  }

  return (
    <Screen title="Transferencia entre cuentas" code="SCR-TRANSFERENCIA">
      <form onSubmit={transferir} noValidate>
        <Stack>
          <Card title="Datos de la transferencia">
            <Grid columns={2}>
              <div data-field="txtCuentaOrigen">
                <TextField
                  label="Cuenta origen"
                  required
                  maxLength={10}
                  hint="10 dígitos"
                  error={errors.txtCuentaOrigen}
                  value={origen}
                  onChange={(v: string) => setOrigen(v.slice(0, 10))}
                />
              </div>

              <div data-field="txtCuentaDestino">
                <TextField
                  label="Cuenta destino"
                  required
                  maxLength={10}
                  error={errors.txtCuentaDestino}
                  value={destino}
                  onChange={(v: string) => setDestino(v.slice(0, 10))}
                />
              </div>

              <div data-field="txtMonto">
                <TextField
                  label="Monto (USD)"
                  required
                  numeric
                  maxLength={9}
                  hint="Entre 1 y 10.000"
                  error={errors.txtMonto}
                  value={monto}
                  onChange={(v: string) => setMonto(v.slice(0, 9))}
                />
              </div>

              <div data-field="ddlTipo">
                <SelectField
                  label="Tipo"
                  options={TIPO_OPTIONS}
                  value={tipo}
                  onChange={(v: string) => setTipo(v.slice(0, 3))}
                />
              </div>
            </Grid>
          </Card>

          <Card title="Resultado">
            <Stack>
              <div>
                <strong>Comisión: </strong>
                <span data-field="lblComision">{comision !== '' ? comision : '—'}</span>
              </div>

              <div data-field="lblMensaje" aria-live="polite">
                {status === 'error' && <Alert tone="error">{mensaje}</Alert>}
                {status === 'success' && <Alert tone="success">{mensaje}</Alert>}
                {status === 'idle' && mensaje !== '' && <Alert tone="info">{mensaje}</Alert>}
                {status === 'idle' && mensaje === '' && (
                  <span>Complete los datos y presione Transferir.</span>
                )}
              </div>
            </Stack>
          </Card>

          <div>
            <Button data-action="ENTER" type="submit" variant="primary">
              Transferir
            </Button>{' '}
            <Button data-action="btnCancelar" type="button" variant="secondary" onClick={cancelar}>
              Cancelar
            </Button>
          </div>
        </Stack>
      </form>
    </Screen>
  )
}
```

I made three choices where the contract and the prototype differ:

- **Validation:** I kept only the required-field check plus a check that the amount is a number. The prototype's 10-digit and 1–10.000 rules are not in the contract, so I left them to the backend. If the backend rejects the request, its message appears in `lblMensaje`.
- **Account fields:** `txtCuentaOrigen` and `txtCuentaDestino` are not `numeric`, because the contract marks only `txtMonto` as numeric.
- **Tipo field:** `ddlTipo` is a `SelectField`, as in the prototype, with its options capped at 3 characters. If the harness requires a `TextField` with `maxLength={3}` for every input field, this is the one to change.

`btnCancelar` has no target in the contract, so it clears the form instead of calling `navigate`.
